/**
 * BloggerBear public frontend -- plain static single-page app, no build step,
 * no framework, no npm. Hash-based client-side routing:
 *   #/                 -> home / topic list
 *   #/topic/{id}       -> published article list for a topic
 *   #/article/{id}     -> full article view
 *
 * Talks to the public API at window.PUBLIC_API_URL (e.g.
 * "https://xxxx.execute-api.ap-southeast-2.amazonaws.com"), set by
 * config.js (generated by Terraform at deploy time, not by this file).
 *
 * Rendering uses plain DOM APIs (createElement / textContent) rather than
 * innerHTML with interpolated content, so that article titles/bodies (data
 * from our own backend, but ultimately Bedrock-generated free text) can
 * never be interpreted as markup.
 */

(function () {
  "use strict";

  var navEl = document.getElementById("nav");
  var contentEl = document.getElementById("content");

  function apiUrl(path) {
    return window.PUBLIC_API_URL + path;
  }

  function clearChildren(el) {
    while (el.firstChild) {
      el.removeChild(el.firstChild);
    }
  }

  function el(tag, opts) {
    var node = document.createElement(tag);
    opts = opts || {};
    if (opts.text !== undefined) {
      node.textContent = opts.text;
    }
    if (opts.className) {
      node.className = opts.className;
    }
    if (opts.href !== undefined) {
      node.setAttribute("href", opts.href);
    }
    return node;
  }

  function showMessage(text) {
    clearChildren(contentEl);
    contentEl.appendChild(el("p", { text: text }));
  }

  function fetchJson(url) {
    return fetch(url).then(function (response) {
      if (!response.ok) {
        throw new Error("request failed: " + response.status);
      }
      return response.json();
    });
  }

  // --- Nav ------------------------------------------------------------

  function renderNav(topics) {
    clearChildren(navEl);
    topics.forEach(function (topic) {
      var link = el("a", { text: topic.name, href: "#/topic/" + encodeURIComponent(topic.topic_id) });
      navEl.appendChild(link);
    });
  }

  function loadNav() {
    fetchJson(apiUrl("/topics"))
      .then(function (data) {
        renderNav(data.topics || []);
      })
      .catch(function () {
        // Nav failing to load shouldn't block the rest of the page.
        clearChildren(navEl);
      });
  }

  // --- Home -------------------------------------------------------------

  function renderHome(topics) {
    clearChildren(contentEl);
    contentEl.appendChild(el("h1", { text: "Topics" }));

    if (topics.length === 0) {
      contentEl.appendChild(el("p", { text: "No topics yet." }));
      return;
    }

    var list = el("ul", { className: "topic-list" });
    topics.forEach(function (topic) {
      var item = el("li");
      var link = el("a", { text: topic.name, href: "#/topic/" + encodeURIComponent(topic.topic_id) });
      item.appendChild(link);
      list.appendChild(item);
    });
    contentEl.appendChild(list);
  }

  function loadHome() {
    showMessage("Loading topics...");
    fetchJson(apiUrl("/topics"))
      .then(function (data) {
        renderHome(data.topics || []);
      })
      .catch(function () {
        showMessage("Could not load topics right now.");
      });
  }

  // --- Topic article list -------------------------------------------------

  function formatDate(isoString) {
    if (!isoString) {
      return "";
    }
    var date = new Date(isoString);
    if (isNaN(date.getTime())) {
      return isoString;
    }
    return date.toLocaleDateString();
  }

  function renderArticleList(topicId, articles) {
    clearChildren(contentEl);
    contentEl.appendChild(el("h1", { text: topicId }));

    if (articles.length === 0) {
      contentEl.appendChild(el("p", { text: "No published articles yet." }));
      return;
    }

    var list = el("ul", { className: "article-list" });
    articles.forEach(function (article) {
      var item = el("li");
      var link = el("a", {
        text: article.title,
        href: "#/article/" + encodeURIComponent(article.article_id),
      });
      item.appendChild(link);
      item.appendChild(el("span", { className: "article-date", text: " " + formatDate(article.published_at) }));
      list.appendChild(item);
    });
    contentEl.appendChild(list);
  }

  function loadTopicArticles(topicId) {
    showMessage("Loading articles...");
    fetchJson(apiUrl("/articles?topic_id=" + encodeURIComponent(topicId)))
      .then(function (data) {
        renderArticleList(topicId, data.articles || []);
      })
      .catch(function () {
        showMessage("Could not load articles right now.");
      });
  }

  // --- Article detail -----------------------------------------------------

  function renderArticle(article) {
    clearChildren(contentEl);

    contentEl.appendChild(el("h1", { text: article.title }));

    var meta = el("p", { className: "article-meta" });
    meta.appendChild(el("span", { text: "Published " + formatDate(article.published_at) }));
    meta.appendChild(document.createTextNode(" · "));
    meta.appendChild(el("span", { className: "view-count", text: article.view_count + " views" }));
    contentEl.appendChild(meta);

    var body = el("div", { className: "article-body" });
    // Render body as plain text paragraphs, split on blank lines, rather
    // than trusting/parsing it as HTML.
    var paragraphs = String(article.body || "").split(/\n\s*\n/);
    paragraphs.forEach(function (paragraph) {
      if (paragraph.trim() === "") {
        return;
      }
      body.appendChild(el("p", { text: paragraph }));
    });
    contentEl.appendChild(body);

    var sourceRefs = article.source_refs || [];
    if (sourceRefs.length > 0) {
      var sourcesSection = el("footer", { className: "sources-footer" });
      sourcesSection.appendChild(el("h2", { text: "Sources" }));
      var sourcesList = el("ul");
      sourceRefs.forEach(function (ref) {
        var item = el("li");
        var link = el("a", { text: ref.title || ref.url, href: ref.url });
        item.appendChild(link);
        item.appendChild(
          document.createTextNode(" (accessed " + formatDate(ref.accessed_at) + ")")
        );
        sourcesList.appendChild(item);
      });
      sourcesSection.appendChild(sourcesList);
      contentEl.appendChild(sourcesSection);
    }

    contentEl.appendChild(renderFeedback(article.article_id));
  }

  // --- Feedback -----------------------------------------------------------

  function renderFeedback(articleId) {
    var section = el("section", { className: "feedback" });
    section.appendChild(el("h2", { text: "Feedback" }));

    var status = el("p", { className: "feedback-status" });

    var upButton = el("button", { text: "Upvote" });
    var downButton = el("button", { text: "Downvote" });
    var commentLabel = el("label", { text: "Comment (optional)" });
    var commentInput = document.createElement("textarea");
    commentInput.setAttribute("rows", "3");
    commentLabel.appendChild(document.createElement("br"));
    commentLabel.appendChild(commentInput);

    var buttonRow = el("div", { className: "feedback-buttons" });
    buttonRow.appendChild(upButton);
    buttonRow.appendChild(downButton);

    function setDisabled(disabled) {
      upButton.disabled = disabled;
      downButton.disabled = disabled;
      commentInput.disabled = disabled;
    }

    function submitVote(vote) {
      setDisabled(true);
      status.textContent = "Submitting...";

      var commentValue = commentInput.value.trim();
      var payload = { vote: vote, comment: commentValue === "" ? null : commentValue };

      fetch(apiUrl("/articles/" + encodeURIComponent(articleId) + "/feedback"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      })
        .then(function (response) {
          if (!response.ok) {
            throw new Error("request failed: " + response.status);
          }
          status.textContent = "Thanks for your feedback!";
        })
        .catch(function () {
          status.textContent = "Could not submit feedback right now. Please try again.";
          setDisabled(false);
        });
    }

    upButton.addEventListener("click", function () {
      submitVote("up");
    });
    downButton.addEventListener("click", function () {
      submitVote("down");
    });

    section.appendChild(buttonRow);
    section.appendChild(commentLabel);
    section.appendChild(status);
    return section;
  }

  function recordView(articleId) {
    // Best-effort, anonymous view counting -- never blocks rendering and
    // never surfaces an error to the user if it fails.
    fetch(apiUrl("/articles/" + encodeURIComponent(articleId) + "/view"), {
      method: "POST",
    }).catch(function () {
      /* ignore */
    });
  }

  function loadArticle(articleId) {
    showMessage("Loading article...");
    fetchJson(apiUrl("/articles/" + encodeURIComponent(articleId)))
      .then(function (article) {
        renderArticle(article);
        recordView(articleId);
      })
      .catch(function () {
        showMessage("Article not found.");
      });
  }

  // --- Routing --------------------------------------------------------

  function parseRoute(hash) {
    // hash looks like "#/topic/foo" or "#/article/bar" or "#/" or "".
    var path = hash.replace(/^#/, "");
    if (path === "" || path === "/") {
      return { name: "home" };
    }
    var topicMatch = path.match(/^\/topic\/([^/]+)$/);
    if (topicMatch) {
      return { name: "topic", topicId: decodeURIComponent(topicMatch[1]) };
    }
    var articleMatch = path.match(/^\/article\/([^/]+)$/);
    if (articleMatch) {
      return { name: "article", articleId: decodeURIComponent(articleMatch[1]) };
    }
    return { name: "not-found" };
  }

  function route() {
    var current = parseRoute(window.location.hash);
    if (current.name === "home") {
      loadHome();
    } else if (current.name === "topic") {
      loadTopicArticles(current.topicId);
    } else if (current.name === "article") {
      loadArticle(current.articleId);
    } else {
      showMessage("Page not found.");
    }
  }

  function fixRssLinks() {
    // The RSS feed lives on the public API's origin, not this static site's
    // -- config.js sets window.PUBLIC_API_URL before this file runs, so
    // rewrite the placeholder same-origin hrefs from index.html to the real
    // absolute URL rather than leaving them pointing at a 404.
    var rssUrl = apiUrl("/rss.xml");
    var rssLink = document.getElementById("rss-link");
    if (rssLink) {
      rssLink.href = rssUrl;
    }
    var rssAlternate = document.querySelector('link[rel="alternate"][type="application/rss+xml"]');
    if (rssAlternate) {
      rssAlternate.href = rssUrl;
    }
  }

  window.addEventListener("hashchange", route);
  window.addEventListener("DOMContentLoaded", function () {
    fixRssLinks();
    loadNav();
    route();
  });
})();
